def evaluate_scores(scores: np.ndarray, labels: np.ndarray) -> dict:
    """Return both AUC-ROC and AUC-PR for a set of scores."""
    return {
        "auc_roc": roc_auc(scores, labels),
        "auc_pr": auc_pr(scores, labels),
        "auc_pr_trapezoid": auc_pr_trapezoid(scores, labels),
    }

