def auc_pr_trapezoid(scores: np.ndarray, labels: np.ndarray) -> float:
    """Compute AUC-PR via trapezoidal rule on the precision-recall curve."""
    prec, rec, _ = precision_recall_curve(labels, scores)
    # trapezoidal rule (numpy >=2.0 uses trapezoid)
    if hasattr(np, "trapezoid"):
        return float(np.trapezoid(prec, rec))
